-- DO NOT EDIT THIS FILE ONCE IT HAS BEEN APPLIED TO ANY DATABASE.
-- Until then it may still change. After it is applied, every change goes in a
-- new migration file with a later timestamp.
-- ============================================================================
--
-- Schedules booked by the WhatsApp assistant: a queryable marker and a
-- confirmation by staff.
--
-- Add-only: three new nullable columns on lead_schedules, one check constraint
-- on the new column and one partial index. No existing column, row, policy or
-- function is changed. Every existing row keeps booked_via null (made by staff)
-- and confirmed_at null (staff items need no confirmation).
--
-- Why not reuse created_by: it is null for the assistant, but also becomes null
-- when a salesperson row is deleted (on delete set null), so it cannot tell the
-- two apart, and it says nothing about confirmation.
--
-- Depends on 20261114090000_lead_schedules.sql.
-- NOT applied to production by the developer. The project owner reviews and
-- applies it (see docs/schedules.md). Until it is applied the assistant's
-- scheduling tools answer "not set up"; staff schedules keep working.

alter table public.lead_schedules
    add column booked_via text,
    add column confirmed_at timestamptz,
    add column confirmed_by uuid references public.sales_users (id) on delete set null;

alter table public.lead_schedules
    add constraint lead_schedules_booked_via_check
        check (booked_via is null or booked_via = 'whatsapp_ai');

comment on column public.lead_schedules.booked_via is 'whatsapp_ai when the WhatsApp assistant booked it; null when staff did.';
comment on column public.lead_schedules.confirmed_at is 'When staff confirmed a booking made by the assistant. Cleared when the assistant moves it. Always null for staff items.';
comment on column public.lead_schedules.confirmed_by is 'sales_users.id of who confirmed the assistant''s booking.';

-- "Booked by AI, to confirm" lists.
create index idx_lead_schedules_ai_unconfirmed
    on public.lead_schedules (starts_at)
    where booked_via = 'whatsapp_ai' and confirmed_at is null and status = 'scheduled';
